请对以下 case 进行三维加权评分。

=== case_id ===
Case-05-agenda-086

=== 用户原始指令 (query.txt) ===
帮我从日历读今天的会,显示还剩几个,点一下进会议,已加入的标完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我从日历读今天的会,显示还剩几个,点一下进会议,已加入的标完成",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "JoinCalendarMeeting",
        "params": {
          "entityId": {
            "path": "/calendar/nextEvent/entityId"
          },
          "meetingUrl": {
            "path": "/calendar/nextEvent/meetingUrl"
          }
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "calendar": {
        "source": "calendar_mock",
        "dateLabel": "今天",
        "remainingCount": 3,
        "remainingText": "还剩3个会",
        "nextEvent": {
          "entityName": "calendar",
          "entityId": "calendar-agenda-086-next",
          "title": "项目同步会",
          "timeRange": "14:00-14:30",
          "meetingUrl": "calendar://meeting/calendar-agenda-086-next",
          "joinStatus": "已加入",
          "completionStatus": "已完成",
          "actionText": "进会议"
        }
      },
      "state": {
        "loading": false
      }
    }
  },
  "assetCandidates": []
}

